using System.Diagnostics;
using System.Reflection;
using System.Text.Json;
using HarmonyLib;
using PeakWorkshop.Plugin;
using PeakWorkshop.Protocol;
using UnityEngine.SceneManagement;

internal static class Checks
{
    internal const BindingFlags All=BindingFlags.Public|BindingFlags.NonPublic|BindingFlags.Instance|BindingFlags.Static;
    internal static readonly Type Controller=typeof(TrainerPlugin);
    internal static void Set(object owner,string name,object value)=>Controller.GetField(name,All).SetValue(owner,value);
    internal static T Get<T>(object owner,string name)=>(T)Controller.GetField(name,All).GetValue(owner);
    internal static void Tick(TrainerPlugin plugin)=>Controller.GetMethod("Update",All).Invoke(plugin,null);
    internal static WireMessage Handle(TrainerPlugin plugin,WireMessage value,int? revision=null)=>(WireMessage)Controller.GetMethod("Handle",All).Invoke(plugin,new object[]{value,revision??Get<int>(plugin,"_revision")});
    internal static (TrainerPlugin Plugin,GameAdapter Adapter,Harmony Harmony) New()
    {
        SceneManager.Current=new Scene{handle=1,name="scene1"};Harmony.Info.Owners.Clear();
        var controller=new TrainerPlugin();var adapter=new GameAdapter(_=>{});var harmony=new Harmony(TrainerPlugin.PluginId);
        Set(controller,"_game",adapter);Set(controller,"_harmony",harmony);Set(controller,"_lastSeen",Stopwatch.GetTimestamp());Tick(controller);return(controller,adapter,harmony);
    }
    internal static WireMessage Request(TrainerPlugin plugin,string kind="set",string feature="speed")
    {
        var values=FeatureSettings.Defaults();foreach(var value in values)if(value.id==feature)value.enabled=true;
        return new WireMessage{kind=kind,sessionId=Get<string>(plugin,"_sessionId"),controllerId=Get<string>(plugin,"_controllerId"),stateRevision=Get<int>(plugin,"_revision"),features=values};
    }
    internal static void Assert(bool value,string message){if(!value)throw new Exception(message);}
    internal static (WireMessage Reply, bool Stopped) Dispatch(TrainerPlugin plugin,WireMessage request)
    {
        string json=JsonSerializer.Serialize(request,new JsonSerializerOptions{IncludeFields=true});
        var task=(Task<PipeReply>)Controller.GetMethod("DispatchAsync",All).Invoke(plugin,new object[]{json,CancellationToken.None});
        Tick(plugin);
        var reply=task.WaitAsync(TimeSpan.FromSeconds(2)).GetAwaiter().GetResult();
        return (JsonSerializer.Deserialize<WireMessage>(reply.Payload,new JsonSerializerOptions{IncludeFields=true}),reply.StopAfterReply);
    }
    public static int Main(string[] args)
    {
        var tests=new List<(string Name,Action Body)>
        {
            ("Completed clear invalidates duplicate and previously queued mutations without changing switches",()=>{var x=New();Handle(x.Plugin,Request(x.Plugin));var clear=Request(x.Plugin,"clear_status");var oldSet=Request(x.Plugin);var first=Handle(x.Plugin,clear);Assert(first.ok&&first.stateRevision>clear.stateRevision,"Clear did not revise state");Assert(!Handle(x.Plugin,clear).ok&&!Handle(x.Plugin,oldSet,oldSet.stateRevision).ok&&x.Adapter.ClearStatusCalls==1&&x.Adapter.Settings.SpeedEnabled,"Duplicate clear or stale mutation executed");}),
            ("Stopped controller rejects even a direct action call before touching game state",()=>{var x=New();Handle(x.Plugin,Request(x.Plugin,"detach"));var result=Handle(x.Plugin,Request(x.Plugin,"clear_status"));Assert(!result.ok&&result.error=="plugin_stopped"&&x.Adapter.ClearStatusCalls==0,"Stopped clear executed");}),
            ("Clear action executes once through production JSON and preserves all active features",()=>{var x=New();Assert(Handle(x.Plugin,Request(x.Plugin)).ok,"Enable initial feature");var before=x.Adapter.Settings;var request=Request(x.Plugin,"clear_status");request.requestId="one-shot-clear";var result=Dispatch(x.Plugin,request);Assert(result.Reply.ok&&result.Reply.requestId=="one-shot-clear"&&result.Reply.clearStatusAvailable&&x.Adapter.ClearStatusCalls==1&&ReferenceEquals(before,x.Adapter.Settings)&&x.Adapter.Settings.SpeedEnabled&&!result.Stopped,"Clear changed settings or acknowledgement");Dispatch(x.Plugin,new WireMessage());Assert(x.Adapter.ClearStatusCalls==1,"State polling repeated clear action");}),
            ("Clear action rejects missing sessions and stale seen or queued actor revisions",()=>{var x=New();var request=Request(x.Plugin,"clear_status");request.sessionId="foreign";Assert(!Handle(x.Plugin,request).ok,"Foreign clear accepted");request=Request(x.Plugin,"clear_status");request.stateRevision--;Assert(!Handle(x.Plugin,request).ok,"Old UI clear accepted");request=Request(x.Plugin,"clear_status");Assert(!Handle(x.Plugin,request,request.stateRevision-1).ok&&x.Adapter.ClearStatusCalls==0,"Old queued clear executed");}),
            ("Clear action rejects unready actors and unavailable game method before invocation",()=>{var x=New();x.Adapter.Ready=false;var result=Handle(x.Plugin,Request(x.Plugin,"clear_status"));Assert(!result.ok&&result.error=="character_not_ready"&&!result.clearStatusAvailable&&x.Adapter.ClearStatusCalls==0,"Unready clear executed");x.Adapter.Ready=true;x.Adapter.ClearStatusSupported=false;result=Handle(x.Plugin,Request(x.Plugin,"clear_status"));Assert(!result.ok&&result.error=="clear_status_unavailable"&&result.clearStatusReason=="missing status method"&&x.Adapter.ClearStatusCalls==0,"Unsupported clear executed");}),
            ("Clear action failure is reported and is never retried by later polling",()=>{var x=New();x.Adapter.ClearStatusFails=true;var result=Dispatch(x.Plugin,Request(x.Plugin,"clear_status"));Assert(!result.Reply.ok&&result.Reply.error=="clear_status_failed"&&x.Adapter.ClearStatusCalls==1,"Clear failure reported success");Dispatch(x.Plugin,new WireMessage());Assert(x.Adapter.ClearStatusCalls==1,"Failed action retried automatically");}),
            ("Clear capability is disabled in final stopped plugin acknowledgement",()=>{var x=New();var result=Dispatch(x.Plugin,Request(x.Plugin,"detach"));Assert(result.Reply.pluginStopped&&!result.Reply.clearStatusAvailable&&result.Reply.clearStatusReason=="插件已停用。","Stopped snapshot advertised clear action");}),
            ("Production Update carries the concrete nonready reason through JSON",()=>{var x=New();x.Adapter.Ready=false;var result=Dispatch(x.Plugin,new WireMessage());Assert(!result.Reply.characterReady&&result.Reply.characterReadinessMessage==x.Adapter.ReadinessMessage,"Nonready reason lost");var rejected=Dispatch(x.Plugin,Request(x.Plugin));Assert(!rejected.Reply.ok&&rejected.Reply.error=="character_not_ready"&&rejected.Reply.message==x.Adapter.ReadinessMessage&&!x.Adapter.Settings.AnyEnabled,"Nonready apply lost diagnostic or changed state");}),
            ("Readiness loss suspends effects, retains choices, rejects stale requests and recovers",()=>{var x=New();var request=Request(x.Plugin);Assert(Handle(x.Plugin,request).ok,"Initial enable");x.Adapter.Ready=false;Tick(x.Plugin);Assert(x.Adapter.Settings.AnyEnabled&&!x.Adapter.Effective.AnyEnabled&&!Handle(x.Plugin,request).ok,"Readiness suspension lost choices or accepted an old operation");x.Adapter.Ready=true;Tick(x.Plugin);Assert(x.Adapter.Settings.AnyEnabled&&x.Adapter.Effective.AnyEnabled,"Readiness recovery failed to reapply choices");}),
            ("Production Update parses state JSON and serializes all 51 entries through its real codec",()=>{var x=New();var result=Dispatch(x.Plugin,new WireMessage{requestId="actual-json-state"});Assert(result.Reply.ok&&result.Reply.requestId=="actual-json-state"&&result.Reply.features.Length==51&&result.Reply.features.All(v=>!v.enabled)&&!result.Stopped,"Update JSON state incomplete");}),
            ("Production Update parses a full set and reset without a JsonUtility substitute",()=>{var x=New();var request=Request(x.Plugin);request.features[0].value=1.5f;var result=Dispatch(x.Plugin,request);Assert(result.Reply.ok&&x.Adapter.Settings.SpeedEnabled&&x.Adapter.Settings.SpeedMultiplier==1.5f&&result.Reply.features.Count(v=>v.enabled)==1,"Update set JSON lost feature state");var reset=Dispatch(x.Plugin,Request(x.Plugin,"reset"));Assert(reset.Reply.ok&&reset.Reply.features.Length==51&&reset.Reply.features.All(v=>!v.enabled)&&!x.Adapter.Settings.AnyEnabled,"Update reset JSON incomplete");}),
            ("Production Update emits a complete final detach JSON before requesting transport stop",()=>{var x=New();var result=Dispatch(x.Plugin,Request(x.Plugin,"detach"));Assert(result.Stopped&&result.Reply.ok&&result.Reply.pluginStopped&&result.Reply.features.Length==51&&result.Reply.features.All(v=>!v.enabled&&!v.available),"Update final detach JSON incomplete");}),
            ("Actual controller rejects a missing/foreign session before modifying features",()=>{var x=New();var request=Request(x.Plugin);request.sessionId="foreign";Assert(!Handle(x.Plugin,request).ok&&!x.Adapter.Settings.AnyEnabled,"Session bypass");}),
            ("Actual controller rejects stale seen and queued revisions",()=>{var x=New();var request=Request(x.Plugin);request.stateRevision--;Assert(!Handle(x.Plugin,request).ok,"Old UI revision accepted");request.stateRevision++;Assert(!Handle(x.Plugin,request,request.stateRevision-1).ok,"Old queue revision accepted");}),
            ("Actual controller validates the full feature array before any apply",()=>{var x=New();var request=Request(x.Plugin);request.features[0].value=float.NaN;Assert(!Handle(x.Plugin,request).ok&&!x.Adapter.Settings.AnyEnabled,"Invalid parameter applied");request=Request(x.Plugin);request.features[0].id="unknown";Assert(!Handle(x.Plugin,request).ok,"Unknown ID accepted");}),
            ("Actual controller rejects enabled unavailable or nonready actors",()=>{var x=New();x.Adapter.Unavailable.Add("speed");Assert(!Handle(x.Plugin,Request(x.Plugin)).ok,"Unavailable feature enabled");x.Adapter.Unavailable.Clear();x.Adapter.Ready=false;Assert(!Handle(x.Plugin,Request(x.Plugin)).ok,"Dead/notready actor enabled");}),
            ("Actual controller state acknowledgement covers all 51 defaults",()=>{var x=New();var state=Handle(x.Plugin,new WireMessage());Assert(state.ok&&state.features.Length==51&&state.features.All(v=>!v.enabled),"Default state invalid");}),
            ("Actual controller reset disables all 51 accepted controls",()=>{var x=New();var request=Request(x.Plugin);foreach(var value in request.features)value.enabled=true;Assert(Handle(x.Plugin,request).ok,"Full state rejected");var response=Handle(x.Plugin,Request(x.Plugin,"reset"));Assert(response.ok&&response.features.All(v=>!v.enabled)&&!x.Adapter.Settings.AnyEnabled,"Reset incomplete");}),
            ("Actual controller actor and scene transitions invalidate old operations",()=>{var x=New();var old=Request(x.Plugin);Handle(x.Plugin,old);x.Adapter.Changed=true;Tick(x.Plugin);Assert(x.Adapter.Settings.AnyEnabled&&x.Adapter.Effective.AnyEnabled&&Get<int>(x.Plugin,"_revision")>old.stateRevision&&!Handle(x.Plugin,old).ok,"Actor transition retained old state");old=Request(x.Plugin);Handle(x.Plugin,old);SceneManager.Current=new Scene{handle=2,name="scene2"};Tick(x.Plugin);Assert(x.Adapter.Settings.AnyEnabled&&x.Adapter.Effective.AnyEnabled&&!Handle(x.Plugin,old).ok,"Scene transition lost choices or replayed a stale operation");}),
            ("Disconnect and timeout suspend effects and retain controls until a fresh query",()=>{var x=New();Handle(x.Plugin,Request(x.Plugin));Set(x.Plugin,"_disconnectRequested",1);Tick(x.Plugin);Assert(x.Adapter.Settings.AnyEnabled&&!x.Adapter.Effective.AnyEnabled,"Disconnect lost choices or left effects active");Handle(x.Plugin,Request(x.Plugin));Set(x.Plugin,"_lastSeen",Stopwatch.GetTimestamp()-Stopwatch.Frequency*4);Tick(x.Plugin);Assert(x.Adapter.Settings.AnyEnabled&&!x.Adapter.Effective.AnyEnabled,"Timeout lost choices or left effects active");}),
            ("Capability loss pauses only unavailable effects and restores retained choices when available",()=>{var x=New();var old=Request(x.Plugin,"set","fog.stop");Assert(Handle(x.Plugin,old).ok,"Initial fog enable");x.Adapter.Unavailable.Add("fog.stop");Tick(x.Plugin);Assert(x.Adapter.Settings.Enabled("fog.stop")&&!x.Adapter.Effective.Enabled("fog.stop"),"Capability loss erased choice or left effect active");x.Adapter.Unavailable.Clear();Tick(x.Plugin);Assert(x.Adapter.Settings.Enabled("fog.stop")&&x.Adapter.Effective.Enabled("fog.stop"),"Regained authority failed to restore choice");}),
            ("Actual controller detach disables/disposes/unpatches only its own owner and keeps stopped snapshot",()=>{var x=New();Harmony.Info.Owners.AddRange(new[]{TrainerPlugin.PluginId,"other.mod"});Handle(x.Plugin,Request(x.Plugin));var response=Handle(x.Plugin,Request(x.Plugin,"detach"));Assert(response.ok&&response.pluginStopped&&!response.detachAvailable&&response.features.All(v=>!v.enabled&&!v.available),"Detach snapshot invalid");Assert(x.Adapter.Disposed&&x.Harmony.UnpatchCalls==1&&Harmony.Info.Owners.SequenceEqual(new[]{"other.mod"}),"Detach removed foreign patch or skipped dispose");Tick(x.Plugin);Assert(!x.Plugin.enabled,"Component still enabled after transport stopped");}),
            ("Actual controller unpatches and disposes even when restoring world state throws",()=>{var x=New();x.Adapter.ResetThrows=true;var response=Handle(x.Plugin,Request(x.Plugin,"detach"));Assert(response.pluginStopped&&!response.ok&&x.Adapter.Disposed&&x.Harmony.UnpatchCalls==1,"Cleanup exception skipped remaining cleanup");}),
            ("Actual controller OnDisable cleanup is idempotent",()=>{var x=New();Handle(x.Plugin,Request(x.Plugin));var disable=Controller.GetMethod("OnDisable",All);disable.Invoke(x.Plugin,null);disable.Invoke(x.Plugin,null);Assert(x.Harmony.UnpatchCalls==1&&x.Adapter.Disposed&&!x.Adapter.Settings.AnyEnabled,"Duplicate disable leaked/repeated cleanup");})
        };
        tests.AddRange(ControllerRegression.Create());
        var results=new List<object>();int failed=0;
        foreach(var test in tests){try{test.Body();Console.WriteLine("PASS "+test.Name);results.Add(new{name=test.Name,passed=true});}catch(Exception ex){failed++;Console.WriteLine("FAIL "+test.Name+": "+ex);results.Add(new{name=test.Name,passed=false,error=ex.ToString()});}}
        File.WriteAllText(args[0],JsonSerializer.Serialize(new{total=tests.Count,passed=tests.Count-failed,failed,method="Actual TrainerPlugin controller with managed adapter/Unity/Harmony substitutes; no game runtime",createdUtc=DateTime.UtcNow,results},new JsonSerializerOptions{WriteIndented=true}));return failed==0?0:1;
    }
}
